    // [seed arx]
    std::uint8_t *aSource = pWorkSpace->mSource;
    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0x8714D3C303E8680BULL + 0xABD7C7487839913EULL);
    [[maybe_unused]] const std::uint64_t aNonceWordB = TwistMix64::DiffuseB(pNonce * 0xF99801DBD01AC043ULL + 0x9F9E61042ED236FEULL);
