            aOrbiterF = ((aWandererD + RotL64(aIngress, 23U)) + 0xB4CCCE68D5B14E34ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterC = (aWandererH + RotL64(aPrevious, 29U)) + 0x2F1DCEFC30AE843DULL;
            aOrbiterB = (aWandererB + RotL64(aScatter, 41U)) + 0xBD3AB7BF54544335ULL;
            aOrbiterK = (aWandererG + RotL64(aIngress, 58U)) + 0xEAB5FAD31F232E41ULL;
            aOrbiterE = ((aWandererJ + RotL64(aCross, 13U)) + RotL64(aCarry, 41U)) + 0x421CD8E2F7E8AB91ULL;
            aOrbiterI = ((aWandererK + RotL64(aIngress, 3U)) + RotL64(aCarry, 13U)) + 0xBF8B9084ED73C945ULL;
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterD) + 0x0313DF9D8998DB89ULL) + aTwistOrbiterUpdateSaltA[((aIndex + 29U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0x664CE841EF5A9345ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xE0C7463AB84D482DULL), 29U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0xFA3EB82B8C88F348ULL;
