            aOrbiterB = RotL64((aOrbiterB * 0x4DDF90A5B9799F5DULL), 23U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterJ) + 0x05A80CBA4433622DULL) + aTwistOrbiterUpdateSaltB[((aIndex + 28U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterK) ^ 0x5C5485C466B6C83CULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 6U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x2825BF6BF1862EF9ULL), 57U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0xC695375A42CD2045ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0x165B705E57F44BD8ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x89CAF3E3B8A6A075ULL), 47U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0xDF11B1F27D7E18B8ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0xF851661ED0B36432ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xD0D44778A610D58BULL), 19U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0xA0A747C82824BB21ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0x6B8CB5084E1D6B13ULL;
