            //
            aOrbiterE = (((aWandererG + RotL64(aIngress, 37U)) + RotL64(aCarry, 51U)) + 0x16AAF2EC5762683FULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterC = ((aWandererC + RotL64(aCross, 11U)) + RotL64(aCarry, 35U)) + 0x0CE2CE7EAD44F45BULL;
            aOrbiterH = (aWandererF + RotL64(aPrevious, 27U)) + 0x197B31725958CC41ULL;
            aOrbiterI = (((aWandererA + RotL64(aScatter, 43U)) + RotL64(aCarry, 21U)) + 0x5D9CE7D33F441E1BULL) + aTwistOrbiterAssignSaltA[((aIndex + 29U)) & S_SALT1];
            aOrbiterG = (aWandererI + RotL64(aIngress, 3U)) + 0xD3571E87237F479BULL;
            aOrbiterB = (aWandererK + RotL64(aScatter, 60U)) + 0x016E5E6AF1161021ULL;
            aOrbiterD = (aWandererH + RotL64(aPrevious, 53U)) + 0xACB6BF10CEE7BB17ULL;
