            aWandererI = aWandererI + ((((RotL64(aPrevious, 29U) + RotL64(aOrbiterH, 47U)) + aOrbiterJ) + RotL64(aCarry, 53U)) + aTwistWandererUpdateSaltA[((aIndex + 18U)) & S_SALT1]);
