            aOrbiterK = (aWandererD + RotL64(aCross, 34U)) + 0xB1BB51E99F88C926ULL;
            aOrbiterB = (((aWandererG + RotL64(aIngress, 53U)) + RotL64(aCarry, 57U)) + 0x5CC8C0860C62EA2CULL) + aKeyRotateAOrbiterAssignSaltA[(((31U - aIndex) + 22U)) & S_SALT1];
