            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0x4A5F262262E4959CULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterD) ^ 0xCBD4F88D4A9BC7F7ULL) ^ aKeyRotateAOrbiterUpdateSaltF[((aIndex + 27U)) & S_SALT1];
