            aOrbiterF = (aOrbiterF + aOrbiterA) + 0x0ACAEDD6D5842C1DULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterF) ^ 0xA3889202B42F998FULL) ^ aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x6F232C4D45438763ULL), 21U);
