            aIngress = aIngress + (aOrbiterG ^ RotL64(aOrbiterB, 50U));
            aIngress = aIngress + (aOrbiterC ^ RotL64(aOrbiterI, 23U));
            aIngress = aIngress + (aOrbiterD ^ RotL64(aOrbiterJ, 13U));
            aIngress = aIngress + (aOrbiterE ^ RotL64(aOrbiterA, 11U));
            aIngress = aIngress + RotL64(aOrbiterF, 35U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererF = aWandererF + (((RotL64(aCross, 24U) + aOrbiterE) + RotL64(aOrbiterH, 48U)) + RotL64(aCarry, 21U));
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 19U) + RotL64(aOrbiterJ, 41U)) + aOrbiterD);
            aWandererC = aWandererC + (((RotL64(aIngress, 41U) + aOrbiterI) + RotL64(aOrbiterH, 11U)) + RotL64(aCarry, 39U));
            aWandererA = aWandererA ^ ((RotL64(aScatter, 11U) + aOrbiterG) + RotL64(aOrbiterK, 57U));
            aWandererJ = aWandererJ + (((RotL64(aCross, 39U) + aOrbiterB) + RotL64(aOrbiterF, 39U)) + aKeyRotateAWandererUpdateSaltD[((aIndex + 28U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aScatter, 48U) + aOrbiterK) + RotL64(aOrbiterI, 27U));
            aWandererB = aWandererB + ((RotL64(aPrevious, 13U) + aOrbiterK) + RotL64(aOrbiterC, 19U));
            aWandererI = aWandererI ^ ((RotL64(aIngress, 51U) + aOrbiterH) + RotL64(aOrbiterC, 29U));
            aWandererD = aWandererD + (((RotL64(aCross, 57U) + RotL64(aOrbiterG, 34U)) + aOrbiterF) + aKeyRotateAWandererUpdateSaltE[(((31U - aIndex) + 10U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((RotL64(aPrevious, 35U) + RotL64(aOrbiterJ, 51U)) + aOrbiterB);
            aWandererK = aWandererK + ((RotL64(aIngress, 53U) + aOrbiterA) + RotL64(aOrbiterC, 23U));
