            aOrbiterE = (((aWandererK + RotL64(aScatter, 27U)) + RotL64(aCarry, 13U)) + 0x970DD773D57E34A4ULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 28U)) & S_SALT1];
