            aScatter = (RotL64(aCarry, 35U) ^ RotL64(aPrevious, 23U)) + (RotL64(aCross, 5U) + RotL64(aIngress, 50U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterA = ((aWandererJ + RotL64(aPrevious, 44U)) + RotL64(aCarry, 3U)) + 0xE4E055D8D9533FA8ULL;
            aOrbiterB = ((aWandererD + RotL64(aIngress, 13U)) + 0x96580C86B844B30DULL) + aKeyRotateAOrbiterAssignSaltE[(((31U - aIndex) + 21U)) & S_SALT1];
