            aOrbiterK = ((aWandererB + RotL64(aCross, 5U)) + RotL64(aCarry, 41U)) + 0x63B3E4AC23183A8FULL;
            aOrbiterH = ((aWandererG + RotL64(aScatter, 57U)) + RotL64(aCarry, 29U)) + 0x90AE191292FE9745ULL;
            aOrbiterE = ((aWandererA + RotL64(aPrevious, 51U)) + 0x632E2172DEB1D464ULL) + aKeyRotateAOrbiterAssignSaltA[((aIndex + 11U)) & S_SALT1];
            aOrbiterJ = (aWandererE + RotL64(aIngress, 27U)) + 0x49B7F74845EE06F5ULL;
            //
            aOrbiterA = (aOrbiterA + aOrbiterB) + 0xFE89E8508CAE60AAULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0xED43C13A9497C6B4ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x2EEDDD73083E2C1DULL), 19U);
