            aOrbiterD = (aOrbiterD + aOrbiterK) + 0x09E9BC78677EEAF3ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0xC2A51A798EAE540EULL;
            aOrbiterH = RotL64((aOrbiterH * 0x4BDA17EBCA460925ULL), 29U);
