            aOrbiterJ = ((aOrbiterJ + aOrbiterH) + 0xF3F5ACF5E23E5C63ULL) + aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterB = ((aOrbiterB ^ aOrbiterJ) ^ 0x99D308DEFCA34CBCULL) ^ aKeyRotateAOrbiterUpdateSaltA[((aIndex + 29U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x0E6919B6ED548EA1ULL), 57U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0x69B85FA5DFB81D40ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterK) ^ 0x42AC57642A49F4DBULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x539367E649519BF3ULL), 51U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterA) + 0x271FD9689FB44912ULL) + aKeyRotateAOrbiterUpdateSaltB[((aIndex + 27U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0xE2EA55490C05EA5DULL;
            aOrbiterE = RotL64((aOrbiterE * 0xCDEF66ABA438E90BULL), 35U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0xABB36931191A1B1DULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0x109602B34B2AF3D4ULL;
