            //
            aWandererA = aWandererA ^ ((RotL64(aPrevious, 43U) + RotL64(aOrbiterH, 35U)) + aOrbiterD);
            aWandererB = aWandererB + ((RotL64(aIngress, 37U) + aOrbiterJ) + RotL64(aOrbiterE, 29U));
