            aWandererE = aWandererE + ((((RotL64(aCross, 58U) + aOrbiterA) + RotL64(aOrbiterK, 11U)) + RotL64(aCarry, 35U)) + aKeyRotateAWandererUpdateSaltC[((aIndex + 9U)) & S_SALT1]);
