            aOrbiterH = (((aWandererI + RotL64(aPrevious, 5U)) + RotL64(aCarry, 47U)) + 0x62EB33DAAF052851ULL) + aKeyRotateAOrbiterAssignSaltC[((aIndex + 20U)) & S_SALT1];
