            //
            aOrbiterA = ((aWandererI + RotL64(aScatter, 12U)) + RotL64(aCarry, 47U)) + 0xBF2932FB3B5EF4BEULL;
            aOrbiterJ = ((aWandererE + RotL64(aCross, 39U)) + RotL64(aCarry, 5U)) + 0xD05349B9B26E9B47ULL;
            aOrbiterF = (aWandererB + RotL64(aIngress, 5U)) + 0x96955629159FB404ULL;
            aOrbiterG = (((aWandererH + RotL64(aPrevious, 47U)) + RotL64(aCarry, 21U)) + 0x44DEAA1E6B6A1149ULL) + aKeyRotateBOrbiterAssignSaltA[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterC = (aWandererG + RotL64(aScatter, 19U)) + 0x83B96A4E492F3C87ULL;
            aOrbiterE = (aWandererJ + RotL64(aPrevious, 57U)) + 0x6D0931F42A0E4229ULL;
